#include <stdio.h>
#include <math.h>



int main(void) {
    double a, x, next;
    scanf("%lf", &a);
    x = a > 1 ? a : 1;
    while (1) {
        next = (x + a / x) / 2;
        if (fabs(next - x) < 1e-5) break;
        x = next;
    }
    printf("%.6f\n", next);
    return 0;
}
